// n8n Code Node - Flatten Invoices
// This code processes the nested invoice data structure and flattens it

// Get the input data from the previous node
const inputData = $input.all();

// Array to store flattened invoices
const flattenedInvoices = [];

// Process each item from the input
for (const item of inputData) {
  const data = item.json;

  // Check if data is an array (as shown in your example)
  const dataArray = Array.isArray(data) ? data : [data];

  // Process each response object
  for (const response of dataArray) {
    // Check if invoices exist
    if (response.invoices && Array.isArray(response.invoices)) {
      // Flatten each invoice
      for (const invoice of response.invoices) {
        const flatInvoice = {
          // Invoice basic info
          invoice_id: invoice.invoice_id,
          invoice_number: invoice.invoice_number,
          number: invoice.number,

          // Customer info
          customer_id: invoice.customer_id,
          customer_name: invoice.customer_name,
          email: invoice.email,
          phone: invoice.phone,
          country: invoice.country,

          // Dates
          invoice_date: invoice.invoice_date,
          due_date: invoice.due_date,
          created_time: invoice.created_time,
          updated_time: invoice.updated_time,

          // Financial info
          currency_code: invoice.currency_code,
          currency_symbol: invoice.currency_symbol,
          total: invoice.total,
          balance: invoice.balance,

          // Status and type
          status: invoice.status,
          transaction_type: invoice.transaction_type,

          // Billing address (flattened)
          billing_street: invoice.billing_address?.street || invoice.billing_street || '',
          billing_street2: invoice.billing_address?.street2 || invoice.billing_street2 || '',
          billing_city: invoice.billing_address?.city || invoice.billing_city || '',
          billing_state: invoice.billing_address?.state || invoice.billing_state || '',
          billing_zipcode: invoice.billing_address?.zipcode || invoice.billing_zipcode || '',
          billing_country: invoice.billing_address?.country || invoice.billing_country || '',
          billing_phone: invoice.billing_address?.phone || invoice.billing_phone || '',
          billing_fax: invoice.billing_address?.fax || '',
          billing_attention: invoice.billing_address?.attention || '',

          // Shipping address (flattened)
          shipping_street: invoice.shipping_address?.street || invoice.shipping_street || '',
          shipping_street2: invoice.shipping_address?.street2 || invoice.shipping_street2 || '',
          shipping_city: invoice.shipping_address?.city || invoice.shipping_city || '',
          shipping_state: invoice.shipping_address?.state || invoice.shipping_state || '',
          shipping_zipcode: invoice.shipping_address?.zipcode || invoice.shipping_zipcode || '',
          shipping_country: invoice.shipping_address?.country || invoice.shipping_country || '',
          shipping_phone: invoice.shipping_address?.phone || invoice.shipping_phone || '',
          shipping_fax: invoice.shipping_address?.fax || '',
          shipping_attention: invoice.shipping_address?.attention || '',

          // Additional info
          project_name: invoice.project_name,
          reference_number: invoice.reference_number,
          created_by: invoice.created_by,
          salesperson: invoice.salesperson,
          salesperson_name: invoice.salesperson_name,

          // Custom fields
          cf_customer_type: invoice.cf_customer_type,
          cf_customer_type_unformatted: invoice.cf_customer_type_unformatted,
          cf_synced_to_netsuite: invoice.cf_synced_to_netsuite,
          cf_synced_to_netsuite_unformatted: invoice.cf_synced_to_netsuite_unformatted,

          // Flags
          ach_payment_initiated: invoice.ach_payment_initiated,
          is_viewed_by_client: invoice.is_viewed_by_client,
          client_viewed_time: invoice.client_viewed_time,
          has_attachment: invoice.has_attachment,
          is_viewed_in_mail: invoice.is_viewed_in_mail,
          mail_first_viewed_time: invoice.mail_first_viewed_time,
          mail_last_viewed_time: invoice.mail_last_viewed_time,

          // Other fields
          payment_expected_date: invoice.payment_expected_date,
          service_start_date: invoice.service_start_date
        };

        flattenedInvoices.push(flatInvoice);
      }
    }
  }
}

// Return the flattened data in n8n format
return flattenedInvoices.map(invoice => ({ json: invoice }));

// Keep only invoices whose invoice_date is inside the configured window.
const range = $('Set Date Range').first().json;
const fromDate = range.from_date || '';
const toDate = range.to_date || '';

return $input.all().filter(item => {
  const d = item.json.invoice_date || '';
  if (fromDate && d < fromDate) return false;
  if (toDate && d > toDate) return false;
  return true;
});

// Classify the Zoho custom-field update as SUCCESS or ERROR.
const res = $input.first().json || {};
let inv = {};
try { inv = $('return_invoices with zoho custom field').item.json || {}; } catch (e) {}

// Zoho returns code:0 on success; HTTP node puts an `error` object on failure.
const isError = !!res.error || (res.code !== undefined && res.code !== 0);
const message = isError
  ? (res.error?.message || res.message || 'Zoho custom-field update failed')
  : (res.message || 'Custom field updated (cf_synced_to_netsuite = true)');

return [{
  json: {
    status: isError ? 'ERROR' : 'SUCCESS',
    invoice_id: inv.invoice_id || '',
    invoice_number: inv.invoice_number || '',
    customer_name: inv.customer_name || '',
    total: inv.total || 0,
    invoice_date: inv.invoice_date || '',
    zoho_status: inv.status || '',
    message,
  },
}];

// Already-synced invoices (cf_synced_to_netsuite = true) — input is the invoice itself.
const inv = $input.first().json || {};
return [{
  json: {
    status: 'SKIPPED',
    invoice_id: inv.invoice_id || '',
    invoice_number: inv.invoice_number || '',
    customer_name: inv.customer_name || '',
    total: inv.total || 0,
    invoice_date: inv.invoice_date || '',
    zoho_status: inv.status || '',
    message: 'Already synced (cf_synced_to_netsuite = true). Skipped.',
  },
}];

// Aggregate all per-invoice log rows collected through the loop.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.invoice_id || r.invoice_number));

const total = rows.length;
const updated = rows.filter(r => r.status === 'SUCCESS').length;
const skipped = rows.filter(r => r.status === 'SKIPPED').length;
const failed = rows.filter(r => r.status === 'ERROR').length;

return [{
  json: {
    summary: { total, updated, skipped, failed },
    failedRows: rows.filter(r => r.status === 'ERROR'),
    rows,
  },
}];
